entries[347411] = { ["name"] = "Klebriger Dreck", ["text"] = "40 Meter Reichweite\nSofort\nWirft den Dreck auf einen Zielort. Alle Gegner innerhalb von 8 Metern werden um 50% verlangsamt, solange sie sich im Effektbereich befinden. Die Falle bleibt 30 Sek. lang bestehen. Kann nur im Freien in den Schattenlanden verwendet werden." }
entries[347412] = { ["name"] = "Seelenpirscherfalle werfen", ["text"] = "15 Meter ReichweiteWirken in 1 sek. 1 min Abklingzeit\nLegt die Falle innerhalb von 15 Metern um Euch aus. Wenn Gegner darüberlaufen, wird ihre Bewegungsgeschwindigkeit um 30% verringert und sie erleiden ( 131642 * 20 / 4) Schattenschaden im Verlauf von 20 Sek. Kann nur im Freien in den Schattenlanden verwendet werden." }
entries[347413] = { ["name"] = "Nach verlorenen Erinnerungen suchen", ["text"] = "Wirken in 3 sek.\nDurchsucht die Chronik nach verlorenen Erinnerungen und gewährt Euch die Erinnerung an eine legendäre Macht Eurer Klasse, die Ihr noch nicht besitzt." }
