entries[347458] = { ["name"] = "Echo von Eonar", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine geringe Chance, einen Geisterfamiliar an Eure Seite zu beschwören, der für 10 Sek. abhängig von Eurer Rolle Euren Schaden um 10%, Eure Heilung um 10% oder Eure Schadensreduktion um 10% erhöht. 50% dieses Effekts werden auf bis zu 3 Verbündete dupliziert. Dabei werden Verbündete mit derselben Rolle bevorzugt." }
