entries[347509] = { ["name"] = "Besonders opulentes Dunkelmond-Festmahl", ["text"] = "Wirken in 3 sek.\nReagenzien:\nDunkelmond-Dolchmaul (10)\nVerkäufer:\nGalissa Sonnentau\nZone:\nDunkelmond-Insel\nKosten:\n50\n\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her, das sie sättigt und schick einkleidet!\n\nStellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was Eure Vielseitigkeit für 20 Min. erhöht und Euch einkleidet." }
